using System.Linq;
using UnityEngine;
namespace BWVR {
public sealed partial class VillagerResourceGathering:MonoBehaviour {
 public enum Phase { Idle, Approach, Harvest, Carry, Deposit, BuildStore, PlantApproach, Planting, SowApproach, Sowing, FarmApproach, PrepareFarm, ToolApproach, ToolCraft, ToolCelebrate }
 public bool FoodWork=>Active&&(Source?.kind==VillageResource.Wheat||Sowing||PreparingFarm);
 public bool Sowing=>Current==Phase.SowApproach||Current==Phase.Sowing;
 public Phase Current{get;private set;}public bool Active=>Current!=Phase.Idle;public GatheringSource Source{get;private set;}public float Reserved{get;private set;}public int deliveries{get;private set;}
 VillageResources world;IslandNavigator nav;CarryItem actor;HumanoidMotion motion;VillagerRoutine routine;VillagerSocial social;VillagerExploration exploration;VillagerBlockPlay play;int identity;float clock,elapsed,cooldown;GameObject timber,grain,resinJar,axe,seedling,seedPouch;
 ResourceCargo Cargo=>world.State.cargo[identity];
 public void Initialize(VillageResources resources,int index){world=resources;identity=index;nav=GetComponent<IslandNavigator>();actor=GetComponent<CarryItem>();motion=GetComponent<HumanoidMotion>();routine=GetComponent<VillagerRoutine>();social=GetComponent<VillagerSocial>();exploration=GetComponent<VillagerExploration>();play=GetComponent<VillagerBlockPlay>();timber=world.CreateLoad(VillageResource.Wood);grain=world.CreateLoad(VillageResource.Wheat);timber.SetActive(false);grain.SetActive(false);resinJar=world.CreateLoad(VillageResource.Resin);resinJar.SetActive(false);axe=world.CreateAxe();var animator=GetComponentInChildren<Animator>();var hand=animator!=null&&animator.isHuman?animator.GetBoneTransform(HumanBodyBones.RightHand):null;if(hand!=null){axe.transform.SetParent(hand,true);axe.transform.localPosition=Vector3.zero;axe.transform.localRotation=Quaternion.Euler(0,0,-10);}axe.SetActive(false);seedling=world.CreateSeedlingLoad();seedling.SetActive(false);InitializeToolArt();cooldown=2+index*2;}
 bool Busy=>actor.held||social.Active||exploration.Active||play.Active||social.Memory.injury>.7f||social.RecentFright;
 public bool TryBegin(GatheringSource source){if(world.Season.paused||Active||Busy||source==null||!world.Available(source)||!world.GetComponentInParent<QuestSlice>().GetComponentInChildren<IslandDiscoveries>().Reachable(transform.position,source.approach,nav.profile))return false;
  float amount=Mathf.Min(ResourceState.LoadLimit(source.kind),world.State.Find(source.id).remaining,world.FreeSpace(source.kind));if(amount<=.01f)return false;Source=source;Reserved=amount;source.owner=this;if(source.tree!=null)source.tree.ResourceReserved=true;routine.ResetTask();nav.ResetRoute();motion?.LookAt(source.tree!=null?source.tree.transform:source.visual);clock=elapsed=0;Current=Phase.Approach;return true;
 }
 public bool Tick(float dt,bool paused){if(paused||dt<=0||float.IsNaN(dt)||float.IsInfinity(dt))return Active;if(Active&&(Busy||(Source!=null&&!world.Safe(Source)))){Cancel();return false;}
  if(Active&&world.Season.observeWithoutFoodWork&&FoodWork){Cancel();return false;}
  if(!Active){cooldown=Mathf.Max(0,cooldown-dt);if((cooldown>0&&!world.LowFood)||Busy)return false;if(TryBuildStorage()||TrySow()||TryReplant())return true;var choice=world.sources.Where(world.Available).Where(s=>world.GatheringNeed(s.kind)>0).OrderByDescending(s=>{float need=world.GatheringNeed(s.kind);if(s.kind==VillageResource.Wheat&&world.LowFood)need+=2;if(s.kind==VillageResource.Wood&&world.State.NeedsStorage&&world.FreeWood<6)need+=1;if(s.kind==VillageResource.Wood&&!world.State.Find(s.id).felled&&world.State.wood>=6&&world.State.resin<6&&world.ResinReady(s.tree))need-=.2f;float familiar=(routine.role==VillagerRoutine.Role.Farmer&&s.kind==VillageResource.Wheat)||(routine.role==VillagerRoutine.Role.Forester&&s.kind==VillageResource.Wood)?.15f:0;float salvage=s.kind==VillageResource.Wood&&world.State.Find(s.id).felled?.2f:0;return need+familiar+salvage-Vector3.Distance(transform.position,s.approach)/(nav.world.Scale*500);}).FirstOrDefault();if(choice==null||!TryBegin(choice))cooldown=8;return Active;}
  RefreshToolArt();clock+=dt;elapsed+=dt;if(elapsed>150){Cancel();return false;}
  if(ToolAction)return TickTool(dt);
  if(PreparingFarm)return TickFarm(dt);
  if(Current==Phase.SowApproach){motion?.Activity(0);if(nav.MoveTo(Source.approach,transform.lossyScale.y*1.6f,dt)){motion?.Carry(null);seedPouch.SetActive(false);Face(Source.at);motion?.Activity(3);Current=Phase.Sowing;clock=0;}else if(nav.Blocked&&elapsed>5)Cancel();return Active;}
  if(Current==Phase.Sowing){Face(Source.at);if(clock>=SowingSeconds){bool planted=world.State.Sow(Source.id,plannedCrop);Cancel();cooldown=24+identity*4;world.Refresh();if(planted)motion?.React();}return Active;}
  if(Current==Phase.PlantApproach){motion?.Activity(0);if(nav.MoveTo(Source.approach,transform.lossyScale.y*1.6f,dt)){motion?.Carry(null);seedling.SetActive(false);Face(Source.at);motion?.Activity(3);Current=Phase.Planting;clock=0;}else if(nav.Blocked&&elapsed>5)Cancel();return Active;}
  if(Current==Phase.Planting){Face(Source.at);if(clock>=10){bool planted=world.State.Plant(Source.id);Cancel();cooldown=24+identity*4;world.Refresh();if(planted)motion?.React();}return Active;}
  if(Current==Phase.BuildStore){if(nav.MoveTo(world.StoreApproach,transform.lossyScale.y*1.6f,dt)){motion?.Activity(4);if(world.FreeWood<6||world.State.BuildStorage(dt)||!world.State.NeedsStorage){Cancel();world.Refresh();motion?.React();}}else if(nav.Blocked&&elapsed>5)Cancel();return Active;}
  if(Current==Phase.Approach){motion?.Activity(0);if(nav.MoveTo(Source.approach,transform.lossyScale.y*1.6f,dt)){Current=Phase.Harvest;clock=0;Face(Source.at);motion?.Activity(Source.kind==VillageResource.Wood?4:Source.kind==VillageResource.Resin?5:3);axe.SetActive(Source.kind==VillageResource.Wood&&!world.State.Find(Source.id).felled);}else if(nav.Blocked&&elapsed>5)Cancel();}
  else if(Current==Phase.Harvest){Face(Source.at);if(clock>=HarvestSeconds){
   int learned=Source.kind==VillageResource.Wheat?2:Source.kind==VillageResource.Wood&&!world.State.Find(Source.id).felled?1:0;axe.SetActive(false);if(world.State.Harvest(identity,Source.id,Reserved)<=0){Cancel();return false;}practiceKind=learned;if(learned!=0)world.ToolUsed(identity,learned==1?VillageTool.BoundAxe:VillageTool.CultivatingHoe);if(Source.kind==VillageResource.Wood)Source.tree.SetHarvested(true);var load=Source.kind==VillageResource.Wood?timber:Source.kind==VillageResource.Resin?resinJar:grain;load.SetActive(true);load.transform.position=transform.position+Vector3.up*nav.world.Scale;motion?.Carry(load.transform);motion?.Activity(0);Current=Phase.Carry;RefreshToolArt();clock=0;nav.ResetRoute();world.Refresh();
  }}else if(Current==Phase.Carry){if(nav.MoveTo(world.StoreApproach,transform.lossyScale.y*1.4f,dt)){Current=Phase.Deposit;clock=0;motion?.Activity(5);}else if(nav.Blocked&&elapsed>5)Cancel();}
  else if(Current==Phase.Deposit&&clock>=1.2f){float amount=world.State.Deposit(identity);if(amount>0){deliveries++;world.ToolPractice(identity,practiceKind);}Cancel();cooldown=24+identity*4;world.Refresh();motion?.React();}
  return Active;
 }
 public bool TrySow(){if(world.Season.observeWithoutFoodWork||world.Season.paused||Active||Busy||(world.LowFood&&world.sources.Any(s=>s.kind==VillageResource.Wheat&&world.Available(s))))return false;var source=world.sources.Where(world.CanSow).OrderBy(s=>Vector3.Distance(transform.position,s.approach)).FirstOrDefault();return TrySow(source,world.ChooseCrop());}
 FoodCrop plannedCrop;
 public bool TrySow(GatheringSource source,FoodCrop crop=FoodCrop.Wheat){if(world.Season.paused||Active||Busy||!world.CanSow(source)||!System.Enum.IsDefined(typeof(FoodCrop),crop)||!world.GetComponentInParent<QuestSlice>().GetComponentInChildren<IslandDiscoveries>().Reachable(transform.position,source.approach,nav.profile))return false;plannedCrop=crop;Source=source;Reserved=0;source.owner=this;routine.ResetTask();nav.ResetRoute();if(seedPouch==null)seedPouch=world.CreateSeedPouch();seedPouch.SetActive(true);seedPouch.transform.position=transform.position+Vector3.up*nav.world.Scale;motion?.Carry(seedPouch.transform);motion?.LookAt(source.visual);clock=elapsed=0;Current=Phase.SowApproach;return true;}
 public bool TryReplant(){if(world.LowFood||world.Season.paused||Active||Busy)return false;var source=world.sources.Where(world.CanReplant).OrderBy(s=>Vector3.Distance(transform.position,s.approach)).FirstOrDefault();return TryReplant(source);}
 public bool TryReplant(GatheringSource source){if(world.Season.paused||world.LowFood||Active||Busy||source==null||!world.CanReplant(source)||!world.GetComponentInParent<QuestSlice>().GetComponentInChildren<IslandDiscoveries>().Reachable(transform.position,source.approach,nav.profile))return false;Source=source;Reserved=0;source.owner=this;source.tree.ResourceReserved=true;routine.ResetTask();nav.ResetRoute();seedling.SetActive(true);seedling.transform.position=transform.position+Vector3.up*nav.world.Scale;motion?.Carry(seedling.transform);motion?.LookAt(source.visual);clock=elapsed=0;Current=Phase.PlantApproach;return true;}
 public bool TryBuildStorage(){if(world.Season.paused||Active||Busy||!world.State.NeedsStorage||world.FreeWood<6||world.Gatherers.Any(a=>a!=this&&a.Current==Phase.BuildStore))return false;routine.ResetTask();nav.ResetRoute();clock=elapsed=0;Current=Phase.BuildStore;return true;}
 void Face(Vector3 at){var direction=at-transform.position;direction.y=0;if(direction.sqrMagnitude>1e-10f)transform.rotation=Quaternion.LookRotation(direction);}
 public void Cancel(){if(world==null)return;bool owned=Active;world.State.Recover(identity);if(Source!=null&&Source.owner==this){Source.owner=null;if(Source.tree!=null)Source.tree.ResourceReserved=false;}Source=null;Reserved=0;practiceKind=0;Current=Phase.Idle;clock=elapsed=0;cooldown=8;if(timber!=null)timber.SetActive(false);if(grain!=null)grain.SetActive(false);if(resinJar!=null)resinJar.SetActive(false);if(axe!=null)axe.SetActive(false);if(seedling!=null)seedling.SetActive(false);if(seedPouch!=null)seedPouch.SetActive(false);if(owned){motion?.Carry(null);motion?.LookAt(null);motion?.Activity(0);nav?.ResetRoute();routine?.ResetTask();}RefreshToolArt();}
 void OnDisable(){Cancel();}
 void OnDestroy(){if(timber!=null)Destroy(timber);if(grain!=null)Destroy(grain);if(resinJar!=null)Destroy(resinJar);if(axe!=null)Destroy(axe);if(seedling!=null)Destroy(seedling);if(seedPouch!=null)Destroy(seedPouch);if(hoe!=null)Destroy(hoe);}
}
}
